1101	function human(n: number): string {
1102	  if (!Number.isFinite(n) || n <= 0) return "0 B";
1103	  const u = ["B", "KB", "MB", "GB", "TB"];
1104	  let i = 0;
1105	  let v = n;
1106	  while (v >= 1024 && i < u.length - 1) {
1107	    v /= 1024;
1108	    i++;
1109	  }
1110	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${u[i]}`;
1111	}
