1156	    'configfiles {{range $k, $v := .Config.Labels}}{{if eq $k "com.docker.compose.project.config_files"}}{{$v}}{{end}}{{end}}',
1157	    'composewd {{range $k, $v := .Config.Labels}}{{if eq $k "com.docker.compose.project.working_dir"}}{{$v}}{{end}}{{end}}',
1158	    "{{range $p, $bs := .HostConfig.PortBindings}}{{range $bs}}port {{$p}} {{if .HostIp}}{{.HostIp}}{{else}}-{{end}} {{.HostPort}}",
