1239	    "if [ -d /etc/apache2 ] || [ -d /etc/httpd ]; then",
1240	    "  apf=\"\"",
1241	    "  for apc in /etc/apache2/apache2.conf /etc/httpd/conf/httpd.conf; do",
1242	    '    [ -f "$apc" ] && apf="$apf $apc"',
1243	    "  done",
1244	    "  for apd in /etc/apache2/sites-enabled /etc/apache2/conf-enabled /etc/httpd/conf.d /etc/httpd/conf.modules.d; do",
1245	    '    [ -d "$apd" ] || continue',
1246	    '    for f in "$apd"/*; do',
1247	    '      [ -f "$f" ] || continue',
1248	    '      case "$f" in *.bak|*.old|*.save|*.orig|*.dpkg-*|*.rpm*|*~|*.disabled) continue ;; esac',
1249	    '      apf="$apf $f"',
1250	    "    done",
1251	    "  done",
1252	    '  if [ -n "$apf" ]; then',
1253	    "    $TO grep -hE '^[[:space:]]*(ServerName|ServerAlias)[[:space:]]+[^[:space:]]+' $apf 2>/dev/null | head -n 80 | while IFS= read -r sl; do",
1254	    "      printf 'SRVNAME\\t%s\\n' \"$sl\"",
1255	    "    done",
