1318	/** Parse the inventory probe's stdout. Every value is validated before it is kept. */
1319	function parseInventory(stdout: string): SrcInventory {
1320	  const inv = emptyInventory();
1321	  const byId = new Map<string, SrcContainer>();
1322	
1323	  for (const raw of (stdout ?? "").split("\n")) {
1324	    const line = raw.replace(/\r$/, "");
1325	    if (!line) continue;
1326	    const parts = line.split("\t");
1327	    const kind = parts[0];
1328	
1329	    if (kind === "INVENTORY_OK") {
1330	      inv.probed = true;
1331	    } else if (kind === "HASDOCKER") {
1332	      inv.hasDocker = true;
1333	    } else if (kind === "CCOUNT" && parts.length >= 2) {
1334	      const n = Number(parts[1]);
1335	      if (Number.isInteger(n) && n >= 0) inv.containerCount = n;
1336	    } else if (kind === "IMAGE" && parts.length >= 2) {
1337	      const seg = parts.slice(1).join("\t").split("|");
1338	      const ref = clean(seg[0], 255);
1339	      if (!validImageRef(ref) || inv.images.some((i) => i.ref === ref)) continue;
1340	      if (inv.images.length >= 120) continue;
1341	      inv.images.push({ ref, sizeBytes: parseDockerSize(seg[1] ?? ""), local: isLocalImageRef(ref) });
1342	    } else if (kind === "DVOLBYTES" && parts.length >= 2) {
1343	      const n = Number(parts[1]);
1344	      if (Number.isFinite(n) && n > 0) inv.volumeBytes = n;
1345	    } else if (kind === "C" && parts.length >= 3) {
1346	      const cid = clean(parts[1], 64);
1347	      if (!/^[0-9a-f]{6,64}$/i.test(cid)) continue;
1348	      let c = byId.get(cid);
1349	      if (!c) {
1350	        if (byId.size >= 40) continue;
1351	        c = {
1352	          id: cid, name: "", image: "", state: "", restart: "", netmode: "", runuser: "",
1353	          workdir: "", privileged: false, devices: 0, caps: [], cmd: "", entrypoint: "",
1354	          imagecmd: "", imageentrypoint: "", project: "", configFiles: "", composeWd: "", ports: [], mounts: [], networks: [],
1355	        };
1356	        byId.set(cid, c);
1357	      }
1358	      const body = parts.slice(2).join("\t");
